package com.muthumol.player.dummy;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowLooper;import org.drinkless.tdlib.TdApi;import java.util.concurrent.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=25)
public class WatchSyncTest {
 @Test public void writesSchemaValidSavedMessageAndImportsDeviceLocalMedia()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();c.getSharedPreferences("watch-sync",0).edit().clear().commit();final TdApi.SendMessage[] sent={null};final TdApi.Message[] cloud={null};WatchSync sync=new WatchSync(c,(name,args)->{if(name.equals("GetMe")){TdApi.User user=new TdApi.User();user.id=777;return user;}if(name.equals("CreatePrivateChat")){TdApi.Chat chat=new TdApi.Chat();chat.id=777;return chat;}if(name.equals("SearchChatMessages"))return new TdApi.FoundChatMessages(cloud[0]==null?0:1,cloud[0]==null?new TdApi.Message[0]:new TdApi.Message[]{cloud[0]},0);if(name.equals("SendMessage")){sent[0]=(TdApi.SendMessage)TelegramBridge.obj(name,args);TdApi.Message msg=new TdApi.Message();msg.id=321;return msg;}if(name.equals("GetMessage")){TdApi.Message local=TelegramLibraryTest.video(-100,91);((TdApi.MessageVideo)local.content).video.fileName="Lost.S01E01.mkv";return local;}throw new AssertionError(name);});boolean ready=sync.tg.ready;sync.tg.ready=true;try{Movie m=Movie.fromMessage(TelegramLibraryTest.video(-100,91),-100);m.title="Lost.S01E01.mkv";sync.record(m,120000,3000000,false);sync.sync(null,true);sync.worker.submit(()->{}).get(5,TimeUnit.SECONDS);ShadowLooper.idleMainLooper();assertNotNull(sync.status,sent[0]);assertEquals(777,sent[0].chatId);TdApi.InputMessageText text=(TdApi.InputMessageText)sent[0].inputMessageContent;assertTrue(text.text.text.startsWith(WatchSync.TAG));org.json.JSONObject remote=new org.json.JSONObject(text.text.text.substring(WatchSync.TAG.length()+1));remote.put("updated",remote.getLong("updated")+1000).put("position",240000).put("watched",true);TdApi.Message msg=new TdApi.Message();msg.id=321;TdApi.MessageText content=new TdApi.MessageText();content.text=new TdApi.FormattedText(WatchSync.TAG+"\n"+remote,new TdApi.TextEntity[0]);msg.content=content;cloud[0]=msg;sync.sync(null,true);sync.worker.submit(()->{}).get(5,TimeUnit.SECONDS);ShadowLooper.idleMainLooper();assertEquals(240000,m.savedPosition(c));assertTrue("Imported watched status: "+sync.status,new TvLibrary(c).marked(m,"watched"));}finally{sync.tg.ready=ready;sync.ui.removeCallbacksAndMessages(null);sync.worker.shutdownNow();}}
}
